/// A structured MXC failure projected into every generated SDK.
/// </summary>
public interface IBindingException {
    /// <summary>
    /// Returns the stable snake-case error code.
    /// </summary>
    string Code();
    /// <summary>
    /// Returns the human-readable failure message.
    /// </summary>
    string Message();
    /// <summary>
    /// Returns the native status code, when available.
    /// </summary>
    string? NativeCode();
    /// <summary>
    /// Returns the native operation that failed, when available.
    /// </summary>
    string? Operation();
    /// <summary>
    /// Returns an actionable remediation hint, when available.
    /// </summary>
    string? Remediation();
}
/// <summary>
/// A structured MXC failure projected into every generated SDK.
/// </summary>
public class BindingException : UniffiException, IBindingException, IDisposable {
    protected ulong pointer;
    private int _wasDestroyed = 0;
    private long _callCounter = 1;

    public BindingException(ulong pointer) {
        this.pointer = pointer;
    }

    ~BindingException() {
        Destroy();
    }

    protected void FreeRustArcPtr() {
        _UniffiHelpers.RustCall((ref UniffiRustCallStatus status) => {
            _UniFFILib.uniffi_mxc_uniffi_fn_free_bindingerror(this.pointer, ref status);
        });
    }

    protected ulong CloneRustArcPtr() {
        return _UniffiHelpers.RustCall((ref UniffiRustCallStatus status) => {
            return _UniFFILib.uniffi_mxc_uniffi_fn_clone_bindingerror(this.pointer, ref status);
        });
    }

    public void Destroy()
    {
        // Only allow a single call to this method.
        if (Interlocked.CompareExchange(ref _wasDestroyed, 1, 0) == 0)
        {
            // This decrement always matches the initial count of 1 given at creation time.
            if (Interlocked.Decrement(ref _callCounter) == 0)
            {
                FreeRustArcPtr();
            }
        }
    }

    public void Dispose()
    {
        Destroy();
        GC.SuppressFinalize(this); // Suppress finalization to avoid unnecessary GC overhead.
